export const STYLES = ".ink-snow{--panel:#ffffff;--panel-soft:#f3f6f8;--ink:#263b49;--muted:#647985;--line:#dce4e9;--accent:#527790;--snow-background:#fff;--snow-aspect:1.6;color-scheme:light;box-sizing:border-box;width:100%;max-width:1040px;margin-inline:auto;padding:24px;background:var(--panel);color:var(--ink);font:14px/1.55 system-ui,-apple-system,\"Segoe UI\",sans-serif;border:1px solid var(--line);border-radius:18px}\n.ink-snow[data-theme=\"dark\"]{--panel:#131d28;--panel-soft:#1a2836;--ink:#e0eaf2;--muted:#9cabb9;--line:#304252;--accent:#90b8d6;color-scheme:dark}\n.ink-snow *{box-sizing:border-box}.ink-snow [hidden]{display:none!important}.ink-snow h2{font-size:20px;letter-spacing:-.035em;margin:0}.ink-snow h2 span{font-size:9px;font-weight:600;letter-spacing:.2em;margin-left:12px;color:var(--muted)}\n.ink-snow .intro{font-size:12px;color:var(--muted);margin:4px 0 0}.ink-snow .studio-top{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:20px}.ink-snow .studio-top .theme-switch{flex:none;min-width:auto}\n.ink-snow .studio-toolbar{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;margin-bottom:14px}.ink-snow .ratio-label{max-width:190px}.ink-snow .file-actions{display:flex;gap:7px;flex-wrap:wrap;margin-left:auto}\n.ink-snow .viz-controls{display:flex;gap:12px 18px;align-items:center;flex-wrap:wrap;margin:12px 0}.ink-snow .form-label{flex:1;min-width:160px;font-size:12px;font-weight:550;display:block}.ink-snow .form-label output{float:right;color:var(--muted);font-variant-numeric:tabular-nums}\n.ink-snow .form-select,.ink-snow input[type=\"number\"]{display:block;width:100%;margin-top:5px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--ink);font:inherit}\n.ink-snow .form-range{width:100%;display:block;accent-color:var(--accent);margin:8px 0}.ink-snow .form-check{display:flex;align-items:center;gap:7px;font-size:12px;flex:1;min-width:160px}.ink-snow input[type=\"checkbox\"]{accent-color:var(--accent)}\n.ink-snow .btn{border:1px solid var(--line);border-radius:8px;padding:8px 11px;background:var(--panel);color:var(--ink);font:inherit;font-size:12px;cursor:pointer}.ink-snow .btn:hover{background:var(--panel-soft)}.ink-snow .btn:disabled{opacity:.45;cursor:default}\n.ink-snow :is(button,input,select,summary):focus-visible{outline:2px solid var(--accent);outline-offset:3px}.ink-snow .text-small{font-size:11px;color:var(--muted);padding:3px 0;margin:5px 0}.ink-snow .tabular-nums{font-variant-numeric:tabular-nums}\n.ink-snow details{border-top:1px solid var(--line);margin-top:18px;padding-top:15px}.ink-snow summary{cursor:pointer;font-size:13px;font-weight:600}.ink-snow .legacy-settings>summary{color:var(--muted)}\n.ink-snow .color-controls{display:flex;gap:16px;flex-wrap:wrap;align-items:center;margin-top:14px}.ink-snow .color-controls>.form-label{min-width:100px}.ink-snow input[type=\"color\"]{display:block;margin-top:5px;width:100%;height:34px;border:1px solid var(--line);border-radius:7px;background:var(--panel);padding:3px;cursor:pointer}\n.ink-snow .studio-message{font-size:12px;padding:10px 12px;border-radius:8px;background:var(--panel-soft);margin:10px 0}.ink-snow .studio-message[data-error=\"true\"]{color:#bf5959}.ink-snow .custom-aspect{display:flex;gap:8px;align-items:flex-end;font-size:11px}.ink-snow .custom-aspect input{width:68px}\n.ink-snow .snow-stage{position:relative;display:grid;place-items:center;background:var(--snow-background);border-radius:10px;overflow:hidden;width:100%}.ink-snow canvas{display:block;width:min(100%,calc(76vh * var(--snow-aspect)));height:auto;aspect-ratio:var(--snow-aspect);max-width:100%;background:var(--snow-background);touch-action:manipulation}\n.ink-snow .snow-exit{display:none;position:absolute;top:14px;left:14px;z-index:2}.ink-snow .snow-view-message{position:absolute;left:12px;bottom:12px;background:var(--panel);padding:8px 12px}\n.ink-snow .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}\n.ink-snow[data-controls-visible=\"false\"],.ink-snow[data-render-only=\"true\"]{padding:0;max-width:none;border:0;border-radius:0;background:var(--snow-background)}\n.ink-snow[data-controls-visible=\"false\"]>:not(.snow-stage):not(style),.ink-snow[data-render-only=\"true\"]>:not(.snow-stage):not(style){display:none}\n.ink-snow[data-render-only=\"true\"] .snow-exit{display:block;opacity:0;pointer-events:none;transition:opacity .2s}.ink-snow[data-render-only=\"true\"] .snow-stage[data-controls=\"true\"] .snow-exit,.ink-snow .snow-exit:focus-within{opacity:1;pointer-events:auto}\n.ink-snow .snow-stage:is(:fullscreen,:-webkit-full-screen){position:fixed;inset:0;display:grid;place-items:center;width:100vw;height:100vh;background:var(--snow-background);border-radius:0}\n.ink-snow .snow-stage:is(:fullscreen,:-webkit-full-screen) canvas{width:min(100vw,calc(100vh * var(--snow-aspect)));height:auto;max-height:100vh;object-fit:contain}\n@media(max-width:560px){.ink-snow{padding:14px 12px;border-radius:12px}.ink-snow .studio-top{margin-bottom:12px}.ink-snow .form-label,.ink-snow .form-check{min-width:130px}.ink-snow .viz-controls{gap:8px 12px}.ink-snow .file-actions{margin-left:0}.ink-snow .studio-toolbar{gap:10px}.ink-snow .ratio-label{max-width:none;min-width:100%}.ink-snow .color-controls>.form-label{min-width:70px}.ink-snow .color-controls>.form-label:last-child{min-width:100%}.ink-snow .btn{padding:7px 9px}}\n\n/* Automatic aspect has an independent containing box; never derive its height\n   from canvas pixels, which would create ResizeObserver feedback. */\n.ink-snow[data-aspect-mode=\"auto\"] .snow-stage{height:68vh;height:68dvh;min-height:220px;max-height:960px}\n.ink-snow[data-aspect-mode=\"auto\"] canvas{position:absolute;inset:0;width:100%;height:100%;max-width:none;aspect-ratio:auto}\n.ink-snow[data-controls-visible=\"false\"][data-aspect-mode=\"auto\"]{height:100%;min-height:0}\n.ink-snow[data-controls-visible=\"false\"][data-aspect-mode=\"auto\"] .snow-stage{height:100%;min-height:0;max-height:none}\n/* Native fullscreen and the API-denied fallback have the same geometry. */\n.ink-snow[data-render-only=\"true\"]{position:fixed;inset:0;width:100%;height:100%;height:100dvh;margin:0;padding:0;max-width:none;z-index:2147483000}\n.ink-snow[data-render-only=\"true\"] .snow-stage{width:100%;height:100%;min-height:0;max-height:none;border-radius:0}\n.ink-snow[data-render-only=\"true\"] canvas{width:min(100vw,calc(100dvh * var(--snow-aspect)));height:auto;max-height:100%;object-fit:contain}\n.ink-snow[data-render-only=\"true\"][data-aspect-mode=\"auto\"] canvas{position:absolute;inset:0;width:100%;height:100%;max-height:none;aspect-ratio:auto;object-fit:fill}\n.ink-snow .snow-exit{gap:8px;align-items:center}\n.ink-snow[data-render-only=\"true\"] .snow-exit{display:flex}\n.ink-snow[data-read-only=\"true\"] canvas{cursor:none;outline:none}\n.ink-snow[data-read-only=\"true\"] .snow-stage[data-controls=\"true\"] canvas{cursor:default}\n.ink-snow .snow-exit{top:max(12px,env(safe-area-inset-top));left:max(12px,env(safe-area-inset-left))}\n";
